import{_ as o,l as s,o as e,c as n,v as t,p as E,x as r,d as l,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"固件：BIOS 与 UEFI","description":"","frontmatter":{"title":"固件：BIOS 与 UEFI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bios-uefi.md","filePath":"cs/bios-uefi.md","lastUpdated":1789023840000}'),p={name:"cs/bios-uefi.md"};function A(I,a,h,B,S,f){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="固件-bios-与-uefi" tabindex="-1">固件：BIOS 与 UEFI <a class="header-anchor" href="#固件-bios-与-uefi" aria-label="Permalink to &quot;固件：BIOS 与 UEFI&quot;">​</a></h1><div class="epigraph"><p>复位后最先跑的不是内核：固件在 SPI 闪存里，训练 DRAM、枚举 PCIe、提供启动服务，再把控制交给引导加载器。</p><footer>—— 据 UEFI Specification；Intel, PCI Firmware Specification 实践；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/framebuffer-display">上一课</a>的 GOP 由固件提供。<a href="/cs/early-boot">早期启动</a>从引导加载器之后讲内核。缺口是更早的 <strong>BIOS/UEFI</strong>：CPU 复位向量指向只执行闪存，如何变成「有 DRAM、有设备、能读盘」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复位：<a href="/cs/reset-strategy">复位策略</a>后 PC 在复位向量（x86 在高地址别名）。此时 DRAM 未训练，只能用 SRAM/Cache-as-RAM。固件：FSP/AGC 一类训练 <a href="/cs/ddr-protocol">DDR</a>，按 <a href="/cs/pcie-tlp-bar">BAR</a> 枚举，用 <a href="/cs/i2c-spi-uart">SPI</a> 读自己，安装 UEFI 启动服务（磁盘、GOP、时间）。传统 BIOS 用 16 位中断调用；UEFI 用表与协议。缺口不是内核 <code>start_kernel</code>，而是这条<strong>硅启动链</strong>。</p><p>Secure Boot：用密钥验引导加载器，点名，安全课再深。ACPI 表描述 APIC、HPET、NUMA，交给 OS。</p><h3 id="uefi-不是操作系统" tabindex="-1">UEFI 不是操作系统 <a class="header-anchor" href="#uefi-不是操作系统" aria-label="Permalink to &quot;UEFI 不是操作系统&quot;">​</a></h3><p>退出启动服务后多数固件驱动消失，运行时服务子集留下（变量、时间）。把 UEFI 当小型 Linux，设备驱动模型会错。BIOS 调用在长模式下不可用，故现代 OS 依赖 UEFI/ACPI 或设备树。</p><p><span class="marginnote">UEFI 规范是主文献。PCI Firmware Spec 讲枚举。Patterson/Hennessy 的复位启动在 x86 上具体化为本课。核心启动（coreboot）是另一实现，合同类似。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SEC/PEI：CAR、内存训练。DXE：驱动、协议。BDS：启动策略、选盘、链加载。SMM：高特权运行时黑洞，本课承认存在。RISC-V：OpenSBI/BOOTROM 扮演类似角色，无 16 位 BIOS。</p>',11)),(e(),E(d,null,{default:r(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RST%5B%22%E5%A4%8D%E4%BD%8D%E5%90%91%E9%87%8F%22%5D%20--%3E%20CAR%5B%22%E6%97%A0%20DRAM%20%E9%98%B6%E6%AE%B5%22%5D%0A%20%20CAR%20--%3E%20MEM%5B%22DDR%20%E8%AE%AD%E7%BB%83%22%5D%0A%20%20MEM%20--%3E%20ENUM%5B%22PCIe%20%2F%20USB%20%E6%9E%9A%E4%B8%BE%22%5D%0A%20%20ENUM%20--%3E%20BOOT%5B%22%E5%90%AF%E5%8A%A8%E6%9C%8D%E5%8A%A1%20%E2%86%92%20%E5%8A%A0%E8%BD%BD%E5%99%A8%22%5D%0A%20%20BOOT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AISA%20%E5%AF%B9%E7%85%A7%E4%BB%8E%20x86%20%E7%BC%96%E7%A0%81%E5%BC%80%E5%A7%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>内存与 I/O 单元到此：从 bank 到固件把接口交给软件。下一单元对照 x86/ARM/RISC-V 的指令与 ABI 边界。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OS 接手后仍通过 ACPI/UEFI 运行时改启动项、读变量。DMA 与 IOMMU 常在 OS 里才开，固件阶段需谨慎。本课封上 I/O 课序：协议与启动已经能接到内核课已有的早期启动。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CSM 兼容细节全书，不把 ME/PSP 固件引擎当主体。不讨论刷机变砖流程。不进入许可密钥。</p><p>后课默认：复位后固件训练内存并枚举 PCIe；UEFI 启动服务把内核装进来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固件先于内核：训练 DRAM、枚举、启动服务。</li><li>BIOS 中断 vs UEFI 协议；ACPI 描述平台。</li><li>I/O 单元收束；下一课 x86-64 编码。</li><li>出处：UEFI Specification；PCI Firmware Spec；Patterson and Hennessy, COD。</li></ul>',8))])}const C=o(p,[["render",A]]);export{u as __pageData,C as default};
